# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().

reset_julia_backend_state <- function() {
  original_state <- FIMS:::.fims_julia_backend_state$initialized
  withr::defer(
    FIMS:::.fims_julia_backend_state$initialized <- original_state,
    envir = parent.frame()
  )
  FIMS:::.fims_julia_backend_state$initialized <- FALSE
}

reset_cpp_backend_state <- function() {
  original_state <- FIMS:::.fims_cpp_backend_state$available
  withr::defer(
    FIMS:::.fims_cpp_backend_state$available <- original_state,
    envir = parent.frame()
  )
  FIMS:::.fims_cpp_backend_state$available <- FALSE
}

test_that("reset_julia_backend_state restores the Julia initialization flag", {
  FIMS:::.fims_julia_backend_state$initialized <- TRUE
  local({
    reset_julia_backend_state()
    expect_false(FIMS:::.fims_julia_backend_state$initialized)
  })
  expect_true(FIMS:::.fims_julia_backend_state$initialized)
})

test_that("load_fims_cpp_backend installs placeholders when the C++ module is unavailable", {
  reset_cpp_backend_state()
  placeholder_env <- new.env(parent = emptyenv())

  testthat::local_mocked_bindings(
    loadModule = function(...) stop("missing compiled backend"),
    .package = "Rcpp"
  )

  loaded <- FIMS:::.load_fims_cpp_backend(ns = placeholder_env)

  #' @description Test that the optional C++ backend loader returns FALSE when Rcpp module loading fails.
  expect_false(loaded)
  #' @description Test that the optional C++ backend loader marks the compiled backend as unavailable after a failed load.
  expect_false(FIMS:::is_fims_cpp_backend_available())
  #' @description Test that the optional C++ backend loader installs exported placeholders when the compiled backend is unavailable.
  expect_true(exists("CreateTMBModel", envir = placeholder_env, inherits = FALSE))
  #' @description Test that compiled-backend placeholders emit an informative Julia fallback message when called.
  expect_error(
    placeholder_env$CreateTMBModel(),
    regexp = "backend = \"julia\""
  )
})

test_that("Julia backend package scaffolding exists", {
  backend_root <- normalizePath(
    FIMS:::julia_backend_package_path(),
    "/",
    mustWork = TRUE
  )

  #' @description Test that the Julia backend Project.toml exists.
  expect_true(file.exists(file.path(backend_root, "Project.toml")))
  #' @description Test that the Julia backend top-level module exists.
  expect_true(file.exists(file.path(backend_root, "src", "FIMSBackend.jl")))
  #' @description Test that the Julia backend selectivity module exists.
  expect_true(file.exists(file.path(backend_root, "src", "modules", "selectivity.jl")))
  #' @description Test that the Julia backend recruitment module exists.
  expect_true(file.exists(file.path(backend_root, "src", "modules", "recruitment.jl")))
  #' @description Test that the Julia backend population module exists.
  expect_true(file.exists(file.path(backend_root, "src", "modules", "population.jl")))
})

test_that("Julia backend helpers return package paths", {
  backend_path <- FIMS:::julia_backend_package_path()
  module_path <- FIMS:::julia_backend_module_path()
  installed_root <- system.file(package = "FIMS")

  #' @description Test that the Julia backend package path is a character scalar.
  expect_type(backend_path, "character")
  #' @description Test that the Julia backend module path is a character scalar.
  expect_type(module_path, "character")
  #' @description Test that the explicit libname/pkgname lookup resolves the same Julia backend path.
  expect_equal(
    normalizePath(
      FIMS:::julia_backend_package_path(libname = dirname(installed_root), pkgname = "FIMS"),
      "/",
      mustWork = TRUE
    ),
    backend_path
  )
  #' @description Test that the explicit libname/pkgname lookup resolves the same Julia backend module path.
  expect_equal(
    normalizePath(
      FIMS:::julia_backend_module_path(libname = dirname(installed_root), pkgname = "FIMS"),
      "/",
      mustWork = TRUE
    ),
    module_path
  )
})

test_that("initialize_julia_backend installs and instantiates its runtime on demand", {
  reset_julia_backend_state()
  package_path <- withr::local_tempdir()
  module_path <- file.path(package_path, "src", "FIMSBackend.jl")
  dir.create(dirname(module_path))
  file.create(module_path)
  setup_arguments <- NULL
  julia_commands <- character()

  testthat::local_mocked_bindings(
    julia_backend_module_path = function(...) module_path,
    julia_backend_package_path = function(...) package_path,
    .package = "FIMS"
  )
  testthat::local_mocked_bindings(
    julia_setup = function(...) setup_arguments <<- list(...),
    julia_command = function(command, ...) julia_commands <<- c(julia_commands, command),
    .package = "JuliaCall"
  )

  expect_true(FIMS:::initialize_julia_backend())
  expect_true(setup_arguments[["installJulia"]])
  expect_equal(setup_arguments[["version"]], "latest")
  expect_true(any(grepl("Pkg.activate", julia_commands, fixed = TRUE)))
  expect_true("Pkg.instantiate()" %in% julia_commands)
  expect_true(any(grepl("using .FIMSBackend", julia_commands, fixed = TRUE)))
  expect_true(FIMS:::.fims_julia_backend_state$initialized)
})

